module adder_16bit(
    input [15:0] a,
    input [15:0] b,
    input Cin,
    output [15:0] y,
    output Co
);
wire [7:0] sum_a;
wire [7:0] sum_b;
wire carry_out_a;
wire carry_out_b;
wire carry_in_b;

// Instantiate two 8-bit adder modules
adder_8bit adder_a(
    .a(a[7:0]),
    .b(b[7:0]),
    .Cin(Cin),
    .y(sum_a),
    .Co(carry_out_a)
);

adder_8bit adder_b(
    .a(a[15:8]),
    .b(b[15:8]),
    .Cin(carry_out_a),
    .y(sum_b),
    .Co(carry_out_b)
);

assign carry_in_b = carry_out_b;
assign y = {sum_b, sum_a};
assign Co = carry_in_b;

endmodule
